    return sorted(out)

def _walk(path, a, b, out):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in a:
            if k not in b:
                out.append(f"- {path}.{k}: {_fmt(a[k])}")
            else:
                _walk(f"{path}.{k}", a[k], b[k], out)
        for k in b:
